begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','owner@example.invalid',now()),('22222222-2222-4222-8222-222222222222','support@example.invalid',now());
create temporary table fixture(key text primary key,id uuid);
grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into fixture values('brand',public.create_owner_workspace('Owner','Support brand','UTC','','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true));
select throws_ok($$select public.grant_support_session((select id from fixture where key='brand'),'support@example.invalid','Review','operator',25)$$,'22023',null,'Support has a hard 24-hour maximum');
select throws_ok($$select public.grant_support_session((select id from fixture where key='brand'),'unknown@example.invalid','Review','operator',1)$$,'22023',null,'Unknown recipient gets no access');
insert into fixture values('support',public.grant_support_session((select id from fixture where key='brand'),'support@example.invalid','Reconcile source','operator',1));
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_workspaces),1,'Support can read scoped brand');
select ok(public.current_brand_capability((select id from fixture where key='brand'),'integrations.connect'),'Operator may connect sources');
select ok(not public.current_brand_capability((select id from fixture where key='brand'),'workspace.manage'),'Support cannot manage ownership or allowances');
select throws_ok($$select public.grant_support_session((select id from fixture where key='brand'),'support@example.invalid','Escalate','operator',1)$$,'42501',null,'Support cannot extend itself');
insert into fixture values('source',public.register_brand_source((select id from fixture where key='brand'),'shopify','Test shop','support-test.myshopify.com'));
reset role;
update public.brand_sources set state='authorized',version=2 where id=(select id from fixture where key='source');
insert into private.connector_credentials(source_id,brand_id,encrypted_value,key_version,expires_at) values((select id from fixture where key='source'),(select id from fixture where key='brand'),'test-only','test',now()+interval '1 hour');
set local role authenticated;
insert into fixture values('run',public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),gen_random_uuid()));
reset role;
select ok(private.run_authorized((select id from fixture where key='run')),'Support job allowed before expiry');
update public.support_sessions set created_at=now()-interval '2 hours',expires_at=now()-interval '1 hour' where id=(select id from fixture where key='support');
select ok(not private.run_authorized((select id from fixture where key='run')),'Expired support job cannot execute or checkpoint');
set local role authenticated;
select is((select count(*)::int from public.brand_workspaces),0,'Expired session loses actual RLS access');
select ok(not public.current_brand_capability((select id from fixture where key='brand'),'integrations.connect'),'Expired operator capability disappears');
select throws_ok($$select public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),gen_random_uuid())$$,'42501',null,'Expired support cannot queue new work');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into fixture values('second',public.grant_support_session((select id from fixture where key='brand'),'support@example.invalid','Review','analyst',1));
select public.revoke_support_session((select id from fixture where key='brand'),(select id from fixture where key='second'));
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_workspaces),0,'Revocation immediately removes support access');
reset role;
select * from finish();
rollback;
